INTRX.register({"id":"smooth-accordion","title":"Smooth Accordion","cat":"Layout & UI","rootClass":"d-acc","tags":["accordion","grid 0fr","native controls"],"libs":[],"desc":"Three headers share a single open section. Grid tracks follow content height while opacity and the original chevrons resolve independently, including interrupted reversals.","seen":"Pattern family: single-open disclosure groups","hint":"Press · Panels open with eased height and a turning chevron","html":"<div class=\"d-acc\"><div class=\"d-acc-card\"><section class=\"d-acc-item\" data-open=\"false\"><h3 class=\"d-acc-heading\"><button class=\"d-acc-head\" type=\"button\" aria-expanded=\"false\"><span class=\"d-acc-label\">What changes?</span><img class=\"d-acc-right\" src=\"{{asset:layout2-accordion-chevron-right}}\" alt=\"\"><img class=\"d-acc-down\" src=\"{{asset:layout2-accordion-chevron-down}}\" alt=\"\"></button></h3><div class=\"d-acc-body\"><div class=\"d-acc-clip\"><p class=\"d-acc-copy\">One section opens at a time. Press it again to close it.</p></div></div></section><section class=\"d-acc-item\" data-open=\"true\"><h3 class=\"d-acc-heading\"><button class=\"d-acc-head\" type=\"button\" aria-expanded=\"true\"><span class=\"d-acc-label\">How does it move?</span><img class=\"d-acc-right\" src=\"{{asset:layout2-accordion-chevron-right}}\" alt=\"\"><img class=\"d-acc-down\" src=\"{{asset:layout2-accordion-chevron-down}}\" alt=\"\"></button></h3><div class=\"d-acc-body\"><div class=\"d-acc-clip\"><p class=\"d-acc-copy\">Height follows its content with a soft, reversible transition.</p></div></div></section><section class=\"d-acc-item\" data-open=\"false\"><h3 class=\"d-acc-heading\"><button class=\"d-acc-head\" type=\"button\" aria-expanded=\"false\"><span class=\"d-acc-label\">Can I use a keyboard?</span><img class=\"d-acc-right\" src=\"{{asset:layout2-accordion-chevron-right}}\" alt=\"\"><img class=\"d-acc-down\" src=\"{{asset:layout2-accordion-chevron-down}}\" alt=\"\"></button></h3><div class=\"d-acc-body\"><div class=\"d-acc-clip\"><p class=\"d-acc-copy\">Use Tab, Enter or Space. Arrow keys move between headers.</p></div></div></section></div><span class=\"d-acc-status\" role=\"status\"></span></div>","css":".d-acc{position:relative;top:4px;font-family:Geist,system-ui,sans-serif;color:#f1f1f1}.d-acc-card{position:absolute;left:10px;top:0;width:200px;border:1px solid #ffffff0f;border-radius:14px;background:#1c1c1c;overflow:clip;box-shadow:0 1px 2px #0000001f,0 8px 20px -8px #0000002e}.d-acc-heading{margin:0;font-size:13px}.d-acc-head{position:relative;display:block;width:100%;height:40px;padding:0 34px 0 13px;border:0;border-bottom:1px solid #ffffff0d;background:none;color:#9c9c9c;text-align:left;font:500 12px/16px Geist,system-ui,sans-serif;cursor:pointer}.d-acc-item[data-open=\"true\"] .d-acc-head{color:#f1f1f1}.d-acc-head img{position:absolute;right:14px;top:10px;display:block;transition:opacity var(--dur-fast) var(--ease-out),transform var(--dur-fast) var(--ease-out)}.d-acc-down{opacity:0;transform:rotate(-90deg)}.d-acc-item[data-open=\"true\"] .d-acc-right{opacity:0;transform:rotate(90deg)}.d-acc-item[data-open=\"true\"] .d-acc-down{opacity:1;transform:none}.d-acc-body{display:grid;grid-template-rows:0fr;transition:grid-template-rows var(--dur-fast) var(--ease-out)}.d-acc-item[data-open=\"true\"] .d-acc-body{grid-template-rows:1fr}.d-acc-clip{min-height:0;overflow:hidden;opacity:0;transition:opacity 200ms var(--ease-out)}.d-acc-item[data-open=\"true\"] .d-acc-clip{opacity:1}.d-acc-copy{margin:0;padding:10px 13px;font:400 12px/18px Geist,system-ui,sans-serif;color:#9c9c9c}.d-acc-head:focus-visible{outline:2px solid var(--focus-ring);outline-offset:-3px}.d-acc[data-mode=\"thumb\"] .d-acc-card{left:0;top:-4px;width:200px;height:148px}.d-acc[data-mode=\"thumb\"] .d-acc-head{height:36px}.d-acc[data-mode=\"thumb\"] .d-acc-copy{padding:5px 13px 3px;line-height:16px}.d-acc-status{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);font-size:13px}@media(prefers-reduced-motion:reduce){.d-acc-body{transition:none}.d-acc-head img{transform:none!important;transition:opacity var(--dur-quick) var(--ease-out)}.d-acc-clip{transition:opacity var(--dur-quick) var(--ease-out)}}","js":"const items=[...root.querySelectorAll('section')],heads=items.map(item=>item.querySelector('button')),status=root.querySelector('[role=\"status\"]'),uid='accordion-'+Math.random().toString(36).slice(2);let selected=1;root.dataset.mode=ctx.mode;\nfunction paint(){items.forEach((item,i)=>{const open=i===selected;item.dataset.open=String(open);heads[i].setAttribute('aria-expanded',String(open));item.querySelector('.d-acc-body').inert=!open;});root.dataset.open=String(selected);}\nfunction select(i){selected=selected===i?-1:i;paint();status.textContent=selected<0?'All sections closed':heads[selected].textContent.trim()+' expanded';ctx.emit('accordion',{index:selected});}\nheads.forEach((head,i)=>{const body=items[i].querySelector('.d-acc-body');head.setAttribute('aria-label',head.querySelector('.d-acc-label').textContent);head.id=uid+'-head-'+i;body.id=uid+'-body-'+i;body.setAttribute('role','region');body.setAttribute('aria-labelledby',head.id);head.setAttribute('aria-controls',body.id);head.addEventListener('click',()=>select(i));head.addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();e.stopPropagation();heads[e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowDown'?1:2))%3].focus();});});ctx.onAction('next',()=>{selected=(selected+1)%3;paint();status.textContent='Section '+(selected+1)+' expanded';});paint();","prompt":"Match v4 Smooth Accordion184:1703 with a 200x148 clipped hero card filling its200x148 plane, radius14, #1c1c1c. Hero headers are36px and show the real 12px questions; initially the middle answer is open at12px/16px in two lines (5px/3px padding). Preserve original14px right/down assets at right14, top10. Full220x220 retains all three readable question headers and real content at12/18, natural content height,200px card; no thumbnail text squeezing. Single-open activation closes others, reactivating closes all. Grid0fr→1fr250ms ease-out, opacity200ms, chevron rotation/crossfade250ms; CSS reversals are interruptible. Add unique labelled regions, aria-expanded/controls, inert collapsed content, arrow/Home/End header focus. Expose Next section and Reset in shared dock. Reduced motion jumps height and crossfades150ms with no rotations. Preserve all original asset slots. Keep all three original accordion questions as accessible button names in both full and native views. Preserve the complete original model, copy, assets and geometry."});
